import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import '../models/iptv_item.dart';import '../services/iptv_service.dart';import 'player.dart';
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_State();}
class _State extends State<HomeScreen> with SingleTickerProviderStateMixin{late final tabs=TabController(length:3,vsync:this);final m3u=TextEditingController(),server=TextEditingController(),user=TextEditingController(),pass=TextEditingController();List<IptvItem>items=[];bool loading=false;String?error;XtreamSource? source;@override void initState(){super.initState();_restore();}Future<void>_restore()async{final p=await SharedPreferences.getInstance();m3u.text=p.getString('m3u')??'';server.text=p.getString('server')??'';user.text=p.getString('user')??'';pass.text=p.getString('pass')??'';}Future<void>_loadM3u()async{await _run(()=>IptvService.instance.loadM3u(m3u.text.trim()),save:()async{final p=await SharedPreferences.getInstance();await p.setString('m3u',m3u.text.trim());});}Future<void>_loadXtream(IptvKind k)async{final s=XtreamSource(server:server.text.trim(),username:user.text.trim(),password:pass.text);source=s;await _run(()=>switch(k){IptvKind.live:IptvService.instance.loadXtreamLive(s),IptvKind.movie:IptvService.instance.loadXtreamMovies(s),IptvKind.series:IptvService.instance.loadXtreamSeries(s)},save:()async{final p=await SharedPreferences.getInstance();await p.setString('server',s.server);await p.setString('user',s.username);await p.setString('pass',s.password);});}Future<void>_run(Future<List<IptvItem>>Function()f,{Future<void>Function()?save})async{setState((){loading=true;error=null;});try{final v=await f();await save?.call();if(mounted)setState(()=>items=v);}catch(e){if(mounted)setState(()=>error=e.toString());}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('IPTV Lite'),bottom:TabBar(controller:tabs,tabs:const[Tab(text:'Live TV'),Tab(text:'Movies'),Tab(text:'Series')])),body:TabBarView(controller:tabs,children:[_page(IptvKind.live),_page(IptvKind.movie),_page(IptvKind.series)]));Widget _page(IptvKind k){return Column(children:[Padding(padding:const EdgeInsets.all(12),child:Column(children:[_field(m3u,'M3U URL'),_field(server,'Xtream Server'),_field(user,'Username'),_field(pass,'Password',secret:true),SizedBox(width:double.infinity,child:FilledButton(onPressed:loading?null:()=>k==IptvKind.live?_loadM3u():_loadXtream(k),child:Text(k==IptvKind.live?'Load M3U':'Load Xtream'))),if(error!=null)Align(alignment:Alignment.centerLeft,child:Text(error!,style:const TextStyle(color:Colors.redAccent)))])),Expanded(child:loading?const Center(child:CircularProgressIndicator()):items.isEmpty?const Center(child:Text('No IPTV content loaded')):ListView.builder(itemCount:items.length,itemBuilder:(_,i){final x=items[i];return ListTile(leading:x.logo!=null&&x.logo!.startsWith('http')?Image.network(x.logo!,width:52,height:52,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.tv)):const Icon(Icons.tv),title:Text(x.name),subtitle:Text(x.group??''),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>IptvPlayerScreen(item:x))));}))]);}Widget _field(TextEditingController c,String label,{bool secret=false})=>Padding(padding:const EdgeInsets.only(bottom:7),child:TextField(controller:c,obscureText:secret,decoration:InputDecoration(labelText:label,border:const OutlineInputBorder(),isDense:true)));@override void dispose(){tabs.dispose();for(final c in[m3u,server,user,pass])c.dispose();IptvService.instance.dispose();super.dispose();}}
